CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, stamps INTEGER NOT NULL DEFAULT 0, rewards INTEGER NOT NULL DEFAULT 0, redeemed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('stamp','earn','redeem')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, staff_label TEXT NOT NULL DEFAULT '', FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE INDEX IF NOT EXISTS events_customer ON events(customer_id,created_at);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);